import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import {
  createEmployee,
  updateEmployee,
  fetchEmployeeById,
  clearSelectedEmployee,
} from "../features/employee/employeeSlice";

const EmployeeForm = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { id } = useParams();
  const { selectedEmployee } = useSelector((state) => state.employee);

  const [employee, setEmployee] = useState({
    name: "",
    lastname: "",
    email: "",
    position: "",
  });

  useEffect(() => {
    if (id) dispatch(fetchEmployeeById(id));
    else dispatch(clearSelectedEmployee());
  }, [id, dispatch]);

  useEffect(() => {
    if (selectedEmployee) setEmployee(selectedEmployee);
  }, [selectedEmployee]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (id) await dispatch(updateEmployee({ id, employee }));
    else await dispatch(createEmployee(employee));
    navigate("/");
  };

  return (
    <div className="container mt-4">
      <h2 className="card text-center mt-2 bg-light p-2">
        {id ? "Edit Employee" : "Add New Employee"}
      </h2>

      <form onSubmit={handleSubmit}>
        <div className="mt-3 card bg-light p-3">
          <div className="d-flex justify-content-center gap-3 mt-2">
            <input
              className="form-control rounded w-100 p-2"
              type="text"
              placeholder="Name"
              value={employee.name}
              onChange={(e) =>
                setEmployee({ ...employee, name: e.target.value })
              }
            />
            <input
              className="form-control rounded w-100 p-2"
              type="text"
              placeholder="Last Name"
              value={employee.lastname}
              onChange={(e) =>
                setEmployee({ ...employee, lastname: e.target.value })
              }
            />
          </div>

          <div className="d-flex justify-content-center gap-3 mt-3">
            <input
              className="form-control rounded w-100 p-2"
              type="email"
              placeholder="Email"
              value={employee.email}
              onChange={(e) =>
                setEmployee({ ...employee, email: e.target.value })
              }
            />
            <input
              className="form-control rounded w-100 p-2"
              type="text"
              placeholder="Position"
              value={employee.position}
              onChange={(e) =>
                setEmployee({ ...employee, position: e.target.value })
              }
            />
          </div>
        </div>

        <div className="mt-2 text-end mt-3">
          <button type="submit" className="rounded btn btn-primary">
            Save
          </button>
        </div>
      </form>
    </div>
  );
};

export default EmployeeForm;
